  function next(){const w=bp().wizard;if(w.step===1&&!w.source)return C().toast('Selecione a origem do pedido.');if(w.source==='CLASS'&&w.step===2){if(!w.classIds.length)return C().toast('Selecione ao menos uma turma.');prepareStudentsFromClasses(true)}if(w.source!=='STOCK'&&((w.source==='CLASS'&&w.step===3)||(w.source==='STUDENT'&&w.step===2))&&!w.selectedStudentIds.length)return C().toast('Selecione ao menos um aluno.');if(((w.source==='CLASS'&&w.step===4)||(w.source==='STUDENT'&&w.step===3)||(w.source==='STOCK'&&w.step===2))&&!w.bookIds.length)return C().toast('Selecione ao menos um livro configurado.');if(((w.source==='CLASS'&&w.step===5)||(w.source==='STUDENT'&&w.step===4)||(w.source==='STOCK'&&w.step===3))&&consolidate(w).some(item=>item.total_quantity<=0))return C().toast('Informe uma quantidade válida para cada livro.');w.step++;C().renderPage()}
