  async function saveOrder(){
    const w=bp().wizard;if(!w||w.saving)return;
    const items=consolidate(w);
    if(!items.length)return C().toast('Selecione ao menos um livro.');
    for(const item of items){const row=book(item.book_id),errors=productionBookReadyErrors(row);if(errors.length)return C().toast(`${row?.name||'Livro'}: ${errors.join(', ')}.`)}
    const button=document.getElementById('createBookOrderButton');w.saving=true;if(button){button.disabled=true;button.textContent='Criando pedido...'}
    const payload={p_order:{order_date:w.orderDate,period_label:w.period,notes:composeOrderNotes(w.notes,w.paymentTermDays),status:'DRAFT',order_source:w.source},p_classes:classPayloads(w,items),p_recipients:recipientPayloads(w),p_items:items};
    try{
      let order,error;
      ({data:order,error}=await client().rpc('create_production_book_order_v3',payload));
      if(error){
        if(w.source==='STOCK'&&isMissingFlexibleOrderRpc(error)) order=await saveLegacyStockOrder(payload);
        else throw error
      }
      if(!order?.id||!order?.order_number)throw new Error('A RPC não retornou a ordem criada.');
      if(w.editingOrderId){
        const original=stateRows('orders').find(row=>row.id===w.editingOrderId);
        if(original&&original.status!=='CANCELLED'&&original.status!=='COMPLETED'){
          const {error:cancelError}=await client().rpc('advance_production_book_order_status',{p_order_id:original.id,p_next_status:'CANCELLED'});
          if(cancelError)throw cancelError;
        }
        await hideOrder(w.editingOrderId,{replaced_by:order.order_number});
      }
      await C().logAudit('Criou pedido de produção',`${order.order_number} · ${SOURCE_LABEL[w.source]}`);
      w.createdOrder=order;w.step=stepLabels(w).length;await load(true);C().toast(`Pedido ${order.order_number} criado.`);C().renderPage()
    }catch(error){
      console.error('Purple Gestão — pedido não salvo:',error);
      const missing=isMissingFlexibleOrderRpc(error);
      C().toast(missing?'Aplique a migration V3 de pedidos flexíveis para pedidos por turma ou alunos específicos. Nenhum pedido foi criado.':`Não foi possível criar o pedido: ${error.message||error}`)
    }finally{w.saving=false;if(button){button.disabled=false;button.textContent='Criar pedido'}}
  }
