  async function generatePdf(orderId){const order=stateRows('orders').find(row=>row.id===orderId);if(!order)return;if(['CANCELLED','COMPLETED'].includes(order.status))return C().toast('Este pedido não aceita nova geração de ordem.');const popup=window.open('','_blank');if(!popup)return C().toast('Permita pop-ups para gerar a ordem de produção.');popup.document.write('<p style="font-family:Arial;padding:24px">Preparando ordem de produção...</p>');try{await ensureSnapshots(order);let currentStatus=order.status,shouldAdvance=['DRAFT','REVIEWED'].includes(currentStatus);if(currentStatus==='DRAFT'){const {error}=await client().rpc('advance_production_book_order_status',{p_order_id:order.id,p_next_status:'REVIEWED'});if(error)throw error;currentStatus='REVIEWED'}if(currentStatus==='REVIEWED'){const {error}=await client().rpc('advance_production_book_order_status',{p_order_id:order.id,p_next_status:'PDF_GENERATED'});if(error)throw error}await load(true);const refreshed=stateRows('orders').find(row=>row.id===orderId);popup.document.open();popup.document.write(pdfDocument(refreshed));popup.document.close();setTimeout(()=>popup.print(),500);await C().logAudit(shouldAdvance?'Gerou ordem de produção':'Reimprimiu ordem de produção',refreshed.order_number);C().toast('Ordem de produção preparada para PDF.');C().renderPage()}catch(error){popup.close();C().toast(`Não foi possível gerar: ${error.message}`)}}
