  function pdfDocument(order){const items=related(order.id,'items'),totals=orderTotals(order.id),source=orderSource(order),meta=orderMetaFromNotes(order),estimatedPages=items.reduce((sum,item)=>sum+Number(book(item.book_id)?.page_count||0)*Number(item.total_quantity||0),0);return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(order.order_number)} · Ordem de produção</title><style>@page{size:A4;margin:12mm 12mm 14mm}*{box-sizing:border-box}body{margin:0;color:#21142d;font:9.2pt Arial,sans-serif;line-height:1.28}header{display:flex;justify-content:space-between;border-bottom:2px solid #7626ad;padding-bottom:5mm;margin-bottom:6mm}strong{color:#63208d}h1{font-size:22pt;margin:0 0 2.5mm}p{margin:0 0 2.5mm}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:3mm;margin:0 0 5mm}.summary div,.meta div{border:1px solid #ddd4e3;border-radius:3mm;padding:3mm;background:#faf7fc}.summary span,.meta span{display:block;font-size:7.4pt;text-transform:uppercase;color:#75657d;margin-bottom:1mm}.summary b,.meta b{font-size:11pt}.meta{display:grid;grid-template-columns:1fr 1.45fr;gap:3mm;margin:0 0 5mm}.note{border:1px solid #e6dfea;border-radius:3mm;padding:3mm;background:#faf7fc;margin:0 0 4mm}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border-bottom:1px solid #ddd4e3;padding:2.4mm;vertical-align:top;text-align:left}th{font-size:7.2pt;text-transform:uppercase;color:#75657d;background:#faf7fc}td.qty,th.qty,td.pages,th.pages{text-align:center;width:9%}td.book,th.book{width:19%}td.profile,th.profile{width:13%}td.tech,th.tech{width:25%}td.finish,th.finish{width:25%}.book-name{font-size:10.3pt;font-weight:700}.muted{color:#75657d;font-size:7.8pt}.tech-block{display:flex;flex-direction:column;gap:1mm}.tech-block span{display:block}.total td{font-weight:700;border-top:2px solid #7626ad}.order-caption{margin:0 0 4mm}.foot{margin-top:4mm;color:#75657d;font-size:7.8pt}</style></head><body><header><div><strong>PURPLE IDIOMAS</strong><br>Produção de material didático</div><div>${fmtDate(order.order_date)}</div></header><h1>ORDEM DE PRODUÇÃO</h1><p class="order-caption">Pedido <b>${esc(order.order_number)}</b> · ${esc(SOURCE_LABEL[source]||source)} · ${esc(order.period_label)}</p><section class="summary"><div><span>Livros</span><b>${items.length}</b></div><div><span>Exemplares</span><b>${totals.total}</b></div><div><span>Páginas estimadas</span><b>${estimatedPages.toLocaleString('pt-BR')}</b></div><div><span>Origem</span><b>${esc(SOURCE_LABEL[source]||source)}</b></div></section><section class="meta"><div><span>Parcelamento</span><b>${esc(paymentTermLabel(meta.paymentTermDays))}</b></div><div><span>Entrega</span><b>${esc(meta.deliveryAddress)}</b></div></section>${meta.publicNotes?`<p class="note"><b>Observações:</b> ${esc(meta.publicNotes)}</p>`:''}${source==='STOCK'?'<p class="note">Pedido de reposição de estoque. A criação desta ordem não movimenta estoque.</p>':''}<table><thead><tr><th class="book">Livro</th><th class="qty">Qtde</th><th class="pages">Pág.</th><th class="profile">Padrão</th><th class="tech">Especificações padrão</th><th class="finish">Acabamento e observações</th></tr></thead><tbody>${items.map(item=>{const spec=compactBookSpec(item);return `<tr><td class="book"><div class="book-name">${esc(item.book_name_snapshot)}</div></td><td class="qty">${item.total_quantity}</td><td class="pages">${esc(pdfValue(spec.snap.book.pageCount))}</td><td class="profile">${esc(pdfValue(spec.snap.book.printProfileName))}</td><td class="tech"><div class="tech-block">${spec.format}${spec.cover}${spec.inner}</div></td><td class="finish"><div class="tech-block">${spec.finish||'<span class="muted">Sem acabamento adicional informado.</span>'}</div></td></tr>`}).join('')}<tr class="total"><td>Total geral</td><td class="qty">${totals.total}</td><td class="pages">-</td><td class="profile">-</td><td class="tech">-</td><td class="finish">-</td></tr></tbody></table><p class="foot">Resumo técnico consolidado para gráfica. Quantidades de alunos e reserva foram omitidas para privilegiar páginas, padrão gráfico e acabamento.</p></body></html>`}

  window.PurpleBookProduction={render,load,pdfDocument};
